371	    @Test
372	    void concurrentWritesSameRecordKeySamePayloadProduceSingleRecord() throws Exception {
373	        grant("g-1", "subj-a", "RESEARCH").andExpect(status().isOk());
374	        int threads = 8;
375	        ExecutorService pool = Executors.newFixedThreadPool(threads);
376	        CountDownLatch ready = new CountDownLatch(threads);
377	        CountDownLatch start = new CountDownLatch(1);
378	        List<Callable<String>> tasks = new ArrayList<>();
379	        for (int i = 0; i < threads; i++) {
380	            String requestId = "w-concurrent-" + i;
381	            tasks.add(() -> {
382	                ready.countDown();
383	                start.await();
384	                return consentService.write(new RecordWriteRequest(
385	                        requestId, "subj-a", Purpose.RESEARCH, "rec-1", "same-payload")).payload();
